using System.Text.Json;using Npgsql;using UDrive.Api.Common;using UDrive.Api.Models;
namespace UDrive.Api.Services;
public sealed class FinanceService(string connectionString){NpgsqlConnection Open()=>new(connectionString);
public async Task<ServiceResult<FinanceDashboardDto>> DashboardAsync(CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);const string sql=@"select coalesce((select sum(amount) from udrive.payments where status in ('Paid','Verified')),0),coalesce((select sum(refund_amount) from udrive.payments),0),coalesce((select sum(commission_amount) from udrive.driver_earnings),0),coalesce((select sum(available_balance+pending_balance) from udrive.driver_wallets),0),(select count(*) from udrive.driver_payout_requests where status in ('Pending','Approved','Processing')),(select count(*) from udrive.refund_requests where status in ('Pending','Approved','Processing'))";await using var c=new NpgsqlCommand(sql,cn);await using var r=await c.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return ServiceResult<FinanceDashboardDto>.Ok(new(r.GetDecimal(0),r.GetDecimal(1),r.GetDecimal(2),r.GetDecimal(3),r.GetInt32(4),r.GetInt32(5)));}
public async Task<ServiceResult<IReadOnlyList<FinanceTransactionDto>>> TransactionsAsync(string? search,string? status,int page,int pageSize,CancellationToken ct){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);await using var cn=Open();await cn.OpenAsync(ct);const string sql=@"select p.id,coalesce(p.provider_reference,p.id::text),'Payment',u.full_name,b.booking_reference,p.amount,p.currency,p.status,p.created_at from udrive.payments p join udrive.bookings b on b.id=p.booking_id join udrive.users u on u.id=b.customer_user_id where (@status is null or p.status=@status) and (@search is null or b.booking_reference ilike '%'||@search||'%' or u.full_name ilike '%'||@search||'%' or coalesce(p.provider_reference,'') ilike '%'||@search||'%') union all select e.id,e.id::text,'DriverEarning',du.full_name,b.booking_reference,e.net_amount,'PKR',e.status,e.created_at from udrive.driver_earnings e join udrive.bookings b on b.id=e.booking_id join udrive.driver_profiles dp on dp.id=e.driver_profile_id join udrive.users du on du.id=dp.user_id where (@status is null or e.status=@status) and (@search is null or b.booking_reference ilike '%'||@search||'%' or du.full_name ilike '%'||@search||'%') order by created_at desc offset @offset limit @limit";var list=new List<FinanceTransactionDto>();await using var c=new NpgsqlCommand(sql,cn);c.Parameters.AddWithValue("status",(object?)Null(status)??DBNull.Value);c.Parameters.AddWithValue("search",(object?)Null(search)??DBNull.Value);c.Parameters.AddWithValue("offset",(page-1)*pageSize);c.Parameters.AddWithValue("limit",pageSize);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetDecimal(5),r.GetString(6),r.GetString(7),r.GetFieldValue<DateTimeOffset>(8)));return ServiceResult<IReadOnlyList<FinanceTransactionDto>>.Ok(list);}
public async Task<ServiceResult<IReadOnlyList<DriverEarningDto>>> EarningsAsync(CancellationToken ct)=>ServiceResult<IReadOnlyList<DriverEarningDto>>.Ok(await LoadEarningsAsync(null,ct));
public async Task<ServiceResult<IReadOnlyList<DriverWalletDto>>> WalletsAsync(CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<DriverWalletDto>();await using var c=new NpgsqlCommand(@"select w.driver_profile_id,u.full_name,w.pending_balance,w.available_balance,w.paid_balance,w.currency,w.version from udrive.driver_wallets w join udrive.driver_profiles d on d.id=w.driver_profile_id join udrive.users u on u.id=d.user_id order by w.available_balance desc",cn);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetDecimal(2),r.GetDecimal(3),r.GetDecimal(4),r.GetString(5),r.GetInt32(6)));return ServiceResult<IReadOnlyList<DriverWalletDto>>.Ok(list);}
public async Task<ServiceResult<IReadOnlyList<DriverPayoutDto>>> PayoutsAsync(CancellationToken ct)=>ServiceResult<IReadOnlyList<DriverPayoutDto>>.Ok(await LoadPayoutsAsync(null,ct));
public async Task<ServiceResult<IReadOnlyList<RefundRequestDto>>> RefundsAsync(CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<RefundRequestDto>();await using var c=new NpgsqlCommand(@"select rr.id,rr.booking_id,b.booking_reference,u.full_name,rr.amount,rr.cancellation_fee,rr.reason,rr.status,rr.review_notes,rr.version,rr.created_at from udrive.refund_requests rr join udrive.bookings b on b.id=rr.booking_id join udrive.users u on u.id=b.customer_user_id order by rr.created_at desc",cn);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),r.GetDecimal(5),r.GetString(6),r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.GetInt32(9),r.GetFieldValue<DateTimeOffset>(10)));return ServiceResult<IReadOnlyList<RefundRequestDto>>.Ok(list);}
public async Task<ServiceResult<IReadOnlyList<CommissionRuleDto>>> CommissionRulesAsync(CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<CommissionRuleDto>();await using var c=new NpgsqlCommand(@"select id,name,percentage,booking_type,city,driver_profile_id,is_active,effective_from,effective_to from udrive.commission_rules order by is_active desc,effective_from desc",cn);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetDecimal(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetGuid(5),r.GetBoolean(6),r.GetFieldValue<DateTimeOffset>(7),r.IsDBNull(8)?null:r.GetFieldValue<DateTimeOffset>(8)));return ServiceResult<IReadOnlyList<CommissionRuleDto>>.Ok(list);}
public async Task<ServiceResult<DriverFinanceSummaryDto>> DriverSummaryAsync(Guid userId,CancellationToken ct){var driver=await DriverIdAsync(userId,ct);if(driver is null)return ServiceResult<DriverFinanceSummaryDto>.Fail(404,"driver_not_found","Driver profile not found.");await EnsureWalletAsync(driver.Value,ct);var wallets=(await WalletsAsync(ct)).Data!;var wallet=wallets.First(x=>x.DriverProfileId==driver);var earnings=await LoadEarningsAsync(driver,ct);var payouts=await LoadPayoutsAsync(driver,ct);var entries=await LoadEntriesAsync(driver.Value,ct);return ServiceResult<DriverFinanceSummaryDto>.Ok(new(wallet,earnings,entries,payouts));}
public async Task<ServiceResult<DriverPayoutDto>> CreatePayoutAsync(Guid userId,CreatePayoutRequest req,CancellationToken ct){var driver=await DriverIdAsync(userId,ct);if(driver is null)return ServiceResult<DriverPayoutDto>.Fail(404,"driver_not_found","Driver profile not found.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);var wallet=await LockWalletAsync(cn,tx,driver.Value,ct);if(wallet.Version!=req.ExpectedWalletVersion)return ServiceResult<DriverPayoutDto>.Fail(409,"wallet_changed","Wallet changed. Refresh and retry.");if(req.Amount>wallet.Available)return ServiceResult<DriverPayoutDto>.Fail(422,"insufficient_balance","Requested amount exceeds available balance.");if(await ScalarInt(cn,tx,"select count(*) from udrive.driver_payout_requests where driver_profile_id=@d and status in ('Pending','Approved','Processing')",ct,("d",driver.Value))>0)return ServiceResult<DriverPayoutDto>.Fail(409,"payout_pending","A payout request is already active.");var id=Guid.NewGuid();await Exec(cn,tx,@"insert into udrive.driver_payout_requests(id,driver_profile_id,amount,status,payout_method,destination_masked,driver_notes,requested_at,created_at,updated_at) values(@id,@d,@a,'Pending',@m,@dest,@notes,now(),now(),now())",ct,("id",id),("d",driver.Value),("a",req.Amount),("m",req.PayoutMethod),("dest",req.DestinationMasked),("notes",req.Notes));await Exec(cn,tx,"update udrive.driver_wallets set available_balance=available_balance-@a,pending_balance=pending_balance+@a,version=version+1,updated_at=now() where driver_profile_id=@d",ct,("a",req.Amount),("d",driver.Value));await Audit(cn,tx,userId,"payout.requested","DriverPayout",id.ToString(),req,ct);await tx.CommitAsync(ct);return ServiceResult<DriverPayoutDto>.Ok((await LoadPayoutsAsync(driver,ct)).First(x=>x.Id==id));}
public async Task<ServiceResult<bool>> ReviewPayoutAsync(Guid actor,Guid id,ReviewPayoutRequest req,CancellationToken ct){var allowed=new[]{"Approved","Processing","Paid","Rejected","Failed","Cancelled"};if(!allowed.Contains(req.Status))return ServiceResult<bool>.Fail(422,"invalid_status","Invalid payout status.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);await using var c=new NpgsqlCommand("select driver_profile_id,amount,status,version from udrive.driver_payout_requests where id=@id for update",cn,tx);c.Parameters.AddWithValue("id",id);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<bool>.Fail(404,"payout_not_found","Payout not found.");var driver=r.GetGuid(0);var amount=r.GetDecimal(1);var old=r.GetString(2);var version=r.GetInt32(3);await r.DisposeAsync();if(version!=req.ExpectedVersion)return ServiceResult<bool>.Fail(409,"payout_changed","Payout changed. Refresh and retry.");if(old is "Paid" or "Cancelled" or "Rejected")return ServiceResult<bool>.Fail(409,"payout_final","Final payout cannot be changed.");await Exec(cn,tx,"update udrive.driver_payout_requests set status=@s,provider_reference=@p,review_notes=@n,reviewed_by_user_id=@a,reviewed_at=now(),paid_at=case when @s='Paid' then now() else paid_at end,version=version+1,updated_at=now() where id=@id",ct,("s",req.Status),("p",req.ProviderReference),("n",req.ReviewNotes),("a",actor),("id",id));if(req.Status=="Paid"){await Exec(cn,tx,"update udrive.driver_wallets set pending_balance=pending_balance-@x,paid_balance=paid_balance+@x,version=version+1,updated_at=now() where driver_profile_id=@d",ct,("x",amount),("d",driver));await Exec(cn,tx,"update udrive.driver_earnings set status='Paid',paid_at=now(),updated_at=now() where driver_profile_id=@d and status='Available'",ct,("d",driver));}else if(req.Status is "Rejected" or "Failed" or "Cancelled")await Exec(cn,tx,"update udrive.driver_wallets set pending_balance=pending_balance-@x,available_balance=available_balance+@x,version=version+1,updated_at=now() where driver_profile_id=@d",ct,("x",amount),("d",driver));await Audit(cn,tx,actor,"payout.reviewed","DriverPayout",id.ToString(),req,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);}
public async Task<ServiceResult<RefundRequestDto>> CreateRefundAsync(Guid actor,CreateRefundRequest req,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var max=await ScalarDecimal(cn,null,"select coalesce(sum(amount-refund_amount),0) from udrive.payments where booking_id=@b and status in ('Paid','Verified','PartiallyRefunded')",ct,("b",req.BookingId));if(req.Amount+req.CancellationFee>max)return ServiceResult<RefundRequestDto>.Fail(422,"refund_exceeds_paid","Refund plus fee exceeds paid amount.");var id=Guid.NewGuid();await using var c=new NpgsqlCommand(@"insert into udrive.refund_requests(id,booking_id,payment_id,requested_by_user_id,amount,cancellation_fee,reason,status,created_at,updated_at) values(@id,@b,@p,@u,@a,@f,@r,'Pending',now(),now())",cn);c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("b",req.BookingId);c.Parameters.AddWithValue("p",(object?)req.PaymentId??DBNull.Value);c.Parameters.AddWithValue("u",actor);c.Parameters.AddWithValue("a",req.Amount);c.Parameters.AddWithValue("f",req.CancellationFee);c.Parameters.AddWithValue("r",req.Reason);await c.ExecuteNonQueryAsync(ct);return ServiceResult<RefundRequestDto>.Ok((await RefundsAsync(ct)).Data!.First(x=>x.Id==id));}
public async Task<ServiceResult<bool>> ReviewRefundAsync(Guid actor,Guid id,ReviewRefundRequest req,CancellationToken ct){var allowed=new[]{"Approved","Processing","Completed","Rejected","Cancelled"};if(!allowed.Contains(req.Status))return ServiceResult<bool>.Fail(422,"invalid_status","Invalid refund status.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);await using var c=new NpgsqlCommand("select booking_id,payment_id,amount,status,version from udrive.refund_requests where id=@id for update",cn,tx);c.Parameters.AddWithValue("id",id);await using var r=await c.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<bool>.Fail(404,"refund_not_found","Refund not found.");var booking=r.GetGuid(0);var payment=r.IsDBNull(1)?(Guid?)null:r.GetGuid(1);var amount=r.GetDecimal(2);var old=r.GetString(3);var version=r.GetInt32(4);await r.DisposeAsync();if(version!=req.ExpectedVersion)return ServiceResult<bool>.Fail(409,"refund_changed","Refund changed. Refresh and retry.");if(old is "Completed" or "Rejected" or "Cancelled")return ServiceResult<bool>.Fail(409,"refund_final","Final refund cannot be changed.");await Exec(cn,tx,"update udrive.refund_requests set status=@s,provider_reference=@p,review_notes=@n,reviewed_by_user_id=@a,reviewed_at=now(),completed_at=case when @s='Completed' then now() else completed_at end,version=version+1,updated_at=now() where id=@id",ct,("s",req.Status),("p",req.ProviderReference),("n",req.ReviewNotes),("a",actor),("id",id));if(req.Status=="Completed"){if(payment.HasValue)await Exec(cn,tx,"update udrive.payments set refund_amount=refund_amount+@x,status=case when refund_amount+@x>=amount then 'Refunded' else 'PartiallyRefunded' end,updated_at=now() where id=@p",ct,("x",amount),("p",payment.Value));else await Exec(cn,tx,"update udrive.payments set refund_amount=refund_amount+@x,status=case when refund_amount+@x>=amount then 'Refunded' else 'PartiallyRefunded' end,updated_at=now() where booking_id=@b and status in ('Paid','Verified','PartiallyRefunded')",ct,("x",amount),("b",booking));}await Audit(cn,tx,actor,"refund.reviewed","RefundRequest",id.ToString(),req,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);}
public async Task<ServiceResult<CommissionRuleDto>> CreateCommissionRuleAsync(Guid actor,CreateCommissionRuleRequest req,CancellationToken ct){if(req.EffectiveTo.HasValue && req.EffectiveTo.Value<=req.EffectiveFrom)return ServiceResult<CommissionRuleDto>.Fail(422,"invalid_period","Effective-to must be after effective-from.");var id=Guid.NewGuid();await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand(@"insert into udrive.commission_rules(id,name,percentage,booking_type,city,driver_profile_id,is_active,effective_from,effective_to,created_by_user_id,created_at,updated_at) values(@id,@n,@p,@b,@c,@d,true,@f,@t,@u,now(),now())",cn);c.Parameters.AddWithValue("id",id);c.Parameters.AddWithValue("n",req.Name);c.Parameters.AddWithValue("p",req.Percentage);c.Parameters.AddWithValue("b",(object?)req.BookingType??DBNull.Value);c.Parameters.AddWithValue("c",(object?)req.City??DBNull.Value);c.Parameters.AddWithValue("d",(object?)req.DriverProfileId??DBNull.Value);c.Parameters.AddWithValue("f",req.EffectiveFrom);c.Parameters.AddWithValue("t",(object?)req.EffectiveTo??DBNull.Value);c.Parameters.AddWithValue("u",actor);await c.ExecuteNonQueryAsync(ct);return ServiceResult<CommissionRuleDto>.Ok((await CommissionRulesAsync(ct)).Data!.First(x=>x.Id==id));}
public async Task<ServiceResult<bool>> CreateAdjustmentAsync(Guid actor,CreateFinancialAdjustmentRequest req,CancellationToken ct){if(req.Amount==0)return ServiceResult<bool>.Fail(422,"invalid_amount","Adjustment amount cannot be zero.");await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);await EnsureWalletAsync(req.DriverProfileId,ct);var id=Guid.NewGuid();await Exec(cn,tx,"insert into udrive.financial_adjustments(id,driver_profile_id,booking_id,adjustment_type,amount,reason,created_by_user_id,created_at) values(@id,@d,@b,@t,@a,@r,@u,now())",ct,("id",id),("d",req.DriverProfileId),("b",req.BookingId),("t",req.AdjustmentType),("a",req.Amount),("r",req.Reason),("u",actor));await Exec(cn,tx,"update udrive.driver_wallets set available_balance=available_balance+@a,version=version+1,updated_at=now() where driver_profile_id=@d",ct,("a",req.Amount),("d",req.DriverProfileId));await Audit(cn,tx,actor,"wallet.adjusted","DriverWallet",req.DriverProfileId.ToString(),req,ct);await tx.CommitAsync(ct);return ServiceResult<bool>.Ok(true);}
public async Task<ServiceResult<int>> ReconcileCompletedTripsAsync(Guid actor,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var ids=new List<Guid>();await using(var c=new NpgsqlCommand("select id from udrive.bookings where status='Completed' and driver_profile_id is not null and not exists(select 1 from udrive.driver_earnings e where e.booking_id=bookings.id)",cn))await using(var r=await c.ExecuteReaderAsync(ct))while(await r.ReadAsync(ct))ids.Add(r.GetGuid(0));foreach(var id in ids){await using var c=new NpgsqlCommand("select udrive.ensure_driver_earning(@id)",cn);c.Parameters.AddWithValue("id",id);await c.ExecuteNonQueryAsync(ct);}return ServiceResult<int>.Ok(ids.Count,$"Reconciled {ids.Count} completed trips.");}
async Task<IReadOnlyList<DriverEarningDto>> LoadEarningsAsync(Guid? driver,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<DriverEarningDto>();await using var c=new NpgsqlCommand(@"select e.id,e.booking_id,b.booking_reference,u.full_name,e.gross_amount,e.commission_percentage,e.commission_amount,e.net_amount,e.status,e.created_at from udrive.driver_earnings e join udrive.bookings b on b.id=e.booking_id join udrive.driver_profiles d on d.id=e.driver_profile_id join udrive.users u on u.id=d.user_id where (@d is null or e.driver_profile_id=@d) order by e.created_at desc",cn);c.Parameters.AddWithValue("d",(object?)driver??DBNull.Value);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),r.GetDecimal(5),r.GetDecimal(6),r.GetDecimal(7),r.GetString(8),r.GetFieldValue<DateTimeOffset>(9)));return list;}
async Task<IReadOnlyList<DriverPayoutDto>> LoadPayoutsAsync(Guid? driver,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<DriverPayoutDto>();await using var c=new NpgsqlCommand(@"select p.id,p.driver_profile_id,u.full_name,p.amount,p.currency,p.status,p.payout_method,p.destination_masked,p.provider_reference,p.driver_notes,p.review_notes,p.version,p.requested_at from udrive.driver_payout_requests p join udrive.driver_profiles d on d.id=p.driver_profile_id join udrive.users u on u.id=d.user_id where (@d is null or p.driver_profile_id=@d) order by p.requested_at desc",cn);c.Parameters.AddWithValue("d",(object?)driver??DBNull.Value);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetDecimal(3),r.GetString(4),r.GetString(5),r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.IsDBNull(8)?null:r.GetString(8),r.IsDBNull(9)?null:r.GetString(9),r.IsDBNull(10)?null:r.GetString(10),r.GetInt32(11),r.GetFieldValue<DateTimeOffset>(12)));return list;}
async Task<IReadOnlyList<WalletEntryDto>> LoadEntriesAsync(Guid driver,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var list=new List<WalletEntryDto>();await using var c=new NpgsqlCommand(@"select e.id,e.entry_type,e.amount,e.balance_bucket,e.description,e.reference,e.created_at from udrive.driver_wallet_entries e join udrive.driver_wallets w on w.id=e.wallet_id where w.driver_profile_id=@d order by e.created_at desc limit 100",cn);c.Parameters.AddWithValue("d",driver);await using var r=await c.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetDecimal(2),r.GetString(3),r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.GetFieldValue<DateTimeOffset>(6)));return list;}
async Task<Guid?> DriverIdAsync(Guid user,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand("select id from udrive.driver_profiles where user_id=@u",cn);c.Parameters.AddWithValue("u",user);var x=await c.ExecuteScalarAsync(ct);return x is Guid g?g:null;}
async Task EnsureWalletAsync(Guid driver,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);await using var c=new NpgsqlCommand("insert into udrive.driver_wallets(id,driver_profile_id,created_at,updated_at) values(gen_random_uuid(),@d,now(),now()) on conflict(driver_profile_id) do nothing",cn);c.Parameters.AddWithValue("d",driver);await c.ExecuteNonQueryAsync(ct);}
async Task<(decimal Available,int Version)> LockWalletAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid driver,CancellationToken ct){await Exec(cn,tx,"insert into udrive.driver_wallets(id,driver_profile_id,created_at,updated_at) values(gen_random_uuid(),@d,now(),now()) on conflict(driver_profile_id) do nothing",ct,("d",driver));await using var c=new NpgsqlCommand("select available_balance,version from udrive.driver_wallets where driver_profile_id=@d for update",cn,tx);c.Parameters.AddWithValue("d",driver);await using var r=await c.ExecuteReaderAsync(ct);await r.ReadAsync(ct);return(r.GetDecimal(0),r.GetInt32(1));}
static string? Null(string? x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();
static async Task Exec(NpgsqlConnection cn,NpgsqlTransaction? tx,string sql,CancellationToken ct,params(string,object?)[] p){await using var c=new NpgsqlCommand(sql,cn,tx);foreach(var x in p)c.Parameters.AddWithValue(x.Item1,x.Item2??DBNull.Value);await c.ExecuteNonQueryAsync(ct);}
static async Task<int> ScalarInt(NpgsqlConnection cn,NpgsqlTransaction? tx,string sql,CancellationToken ct,params(string,object?)[] p){await using var c=new NpgsqlCommand(sql,cn,tx);foreach(var x in p)c.Parameters.AddWithValue(x.Item1,x.Item2??DBNull.Value);return Convert.ToInt32(await c.ExecuteScalarAsync(ct));}
static async Task<decimal> ScalarDecimal(NpgsqlConnection cn,NpgsqlTransaction? tx,string sql,CancellationToken ct,params(string,object?)[] p){await using var c=new NpgsqlCommand(sql,cn,tx);foreach(var x in p)c.Parameters.AddWithValue(x.Item1,x.Item2??DBNull.Value);return Convert.ToDecimal(await c.ExecuteScalarAsync(ct));}
static Task Audit(NpgsqlConnection cn,NpgsqlTransaction tx,Guid actor,string action,string entity,string id,object changes,CancellationToken ct)=>Exec(cn,tx,"insert into udrive.audit_logs(id,actor_user_id,action,entity_type,entity_id,changes_json,created_at,updated_at) values(gen_random_uuid(),@a,@x,@e,@id,cast(@j as jsonb),now(),now())",ct,("a",actor),("x",action),("e",entity),("id",id),("j",JsonSerializer.Serialize(changes)));
}
